sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film {
    <http://dbpedia.org/resource/Toen_'t_licht_verdween> dbr:Boum_sur_Paris
  }
  ?film(dbo:director | dbp:director) ?director .
  ?director(dbo:deathDate | dbp:dateOfDeath | dbp:deathDate) ?deathDate .
  OPTIONAL {
    ?film rdfs:label ?filmLabel .
    FILTER(lang(?filmLabel) = "en")
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel .
    FILTER(lang(?directorLabel) = "en")
  }
}
ORDER BY ?deathDate
LIMIT 1

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?film ?filmLabel ?dir ?dirLabel ?death WHERE {
  VALUES ?film {
    dbr:The_Fatal_Mistake <http://dbpedia.org/resource/The_Devil's_Hairpin>
  }
  ?film dbo:director ?dir .
  ?dir dbo:deathDate ?death .
  OPTIONAL {
    ?film rdfs:label ?filmLabel .
    FILTER(lang(?filmLabel) = 'en')
  }
  OPTIONAL {
    ?dir rdfs:label ?dirLabel .
    FILTER(lang(?dirLabel) = 'en')
  }
}
ORDER BY DESC(?death)
LIMIT 1

SELECT ?later ?laterLabel ?laterDate ?earlier ?earlierLabel ?earlierDate WHERE {
  VALUES (?p1 ?p2) { (dbr:Gideon_Johnson_Pillow dbr:Holm_J�f8lsen) }
  OPTIONAL { ?p1 dbo:birthDate ?dbo1 }
  OPTIONAL { ?p1 dbp:birthDate ?dbp1 }
  BIND(COALESCE(?dbo1, ?dbp1) AS ?d1)
  OPTIONAL { ?p2 dbo:birthDate ?dbo2 }
  OPTIONAL { ?p2 dbp:birthDate ?dbp2 }
  BIND(COALESCE(?dbo2, ?dbp2) AS ?d2)
  FILTER(?d2 > ?d1)
  BIND(?p2 AS ?later)
  BIND(?d2 AS ?laterDate)
  BIND(?p1 AS ?earlier)
  BIND(?d1 AS ?earlierDate)
  OPTIONAL { ?later rdfs:label ?laterLabel . FILTER(lang(?laterLabel) = "en") }
  OPTIONAL { ?earlier rdfs:label ?earlierLabel . FILTER(lang(?earlierLabel) = "en") }
}

PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?person ?personLabel ?birthDate WHERE {
  VALUES ?person {
    dbr:Marco_de_Luigi dbr:Fabio_Maistro
  }
  OPTIONAL {
    ?person dbo:birthDate ?bd1 .
  }
  OPTIONAL {
    ?person dbp:birthDate ?bd2 .
  }
  OPTIONAL {
    ?person dbp:birth_date ?bd3 .
  }
  BIND(coalesce(?bd1 , ?bd2 , ?bd3) AS ?birthDate)
  OPTIONAL {
    ?person rdfs:label ?personLabel
    FILTER(lang(?personLabel) = "en")
  }
}
ORDER BY ASC(?birthDate)
LIMIT 1

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?film ?filmLabel ?director ?directorLabel ?bdate WHERE {
  VALUES ?film {
    <http://dbpedia.org/resource/The_Gamecock_(film)> dbr:Monster_a_Go-Go
  }
  {
    SELECT ?film(MIN(?b) AS ?minBirth) WHERE {
      ?film dbo:director ?d .
      ?d dbo:birthDate ?b .
    }
    GROUP BY ?film
  }
  ?film dbo:director ?director .
  ?director dbo:birthDate ?bdate .
  FILTER(?bdate = ?minBirth)
  OPTIONAL {
    ?film rdfs:label ?filmLabel .
    FILTER(lang(?filmLabel) = "en")
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel .
    FILTER(lang(?directorLabel) = "en")
  }
}
ORDER BY ?film

