PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?person ?personLabel ?birth ?death ?ageYears WHERE {
  VALUES ?person {
    dbr:Jean-Rodolphe_Perronet dbr:Gunnar_Wiklund
  }
  OPTIONAL {
    ?person dbo:birthDate ?b1 .
  }
  OPTIONAL {
    ?person dbp:birthDate ?b2 .
  }
  OPTIONAL {
    ?person dbo:deathDate ?d1 .
  }
  OPTIONAL {
    ?person dbp:deathDate ?d2 .
  }
  OPTIONAL {
    ?person dbo:abstract ?abs
    FILTER(lang(?abs) = "en")
  }
  BIND(COALESCE(?b1 , ?b2) AS ?birthRaw)
  BIND(COALESCE(?d1 , ?d2) AS ?deathRaw)
  FILTER(BOUND(?birthRaw))
  BIND(xsd:date(STR(?birthRaw)) AS ?birth)
  BIND(IF(STRSTARTS(STR(?deathRaw) , "--") , xsd:date(CONCAT(REPLACE(STR(?abs) , ".*?(\\d{4}).*?(\\d{4}).*" , "$2") , "-" , REPLACE(STR(?deathRaw) , "^--" , ""))) , xsd:date(STR(?deathRaw))) AS ?death)
  FILTER(BOUND(?death))
  BIND((YEAR(?death) - YEAR(?birth)) AS ?yearDiff)
  BIND(IF((MONTH(?death) < MONTH(?birth)) ||(MONTH(?death) = MONTH(?birth) && DAY(?death) < DAY(?birth)) , 1 , 0) AS ?subtract)
  BIND((?yearDiff - ?subtract) AS ?ageYears)
  OPTIONAL {
    ?person rdfs:label ?personLabel
    FILTER(lang(?personLabel) = "en")
  }
}
ORDER BY DESC(?ageYears)

